def mark_out_of_range(records):
    flagged_records = []
    for patient_record in records:
        hcg_level = patient_record["hcg"]
        flagged_records.append({
            **patient_record,
            "out_of_range": hcg_level < LOW or hcg_level > HIGH,
        })
    return flagged_records

